) AS (
  VALUES 
    (140::BIGINT, 'Excelente profesor, llevaría más cursos de inglés con él. Siempre está dispuesto a ayudar si el estudiante lo necesita; además, cuando tiene que corregirlo, lo hace de una manera muy agradable. Eso sí, se enfoca mucho en la pronunciación. Deja bastantes tareas pero son muy sencillas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-17T00:00:00+00:00'::TIMESTAMPTZ, '712d9dc2a86f8f21d8ed109fb453463172b62e924db75b7f089c02470c701a0c'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'Deja trabajos bastante fáciles de hacer, califica suave y no le molesta explicar las cosas una y otra vez, si no entregaste algo de da tiempo y la oportunidad de enviarlo por correo... si tuviera la oportunidad de llevar el resto de cursos de inglés con el lo haría sin pensar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2026-07-08T00:00:00+00:00'::TIMESTAMPTZ, '0bdec1bf633a236aa3841b311aab4adf3f989835c5c59651503f5076792e77f8'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'Es fácil sacar buena nota, manda muchas tareas y eso le puede ir bajando la nota poco a poco, pero califica suave. Es buena nota'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2026-07-04T00:00:00+00:00'::TIMESTAMPTZ, '8221e63f024d7a540ba8d54d36c989139afc2ccb997c003b1130224e40a30d30'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'Es un buen profe, la unica queja es que cuiden del compañero iDl0Ya donde alinee que el profe este de malas (cuesta) ahi anda odioso y pagamos todos. Pero en general cuesta que pase eso. Brinda ayuda se preocupa por los estudiantes que les cuesta'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, '6a0bc41f1cdbfaf47e859ca98b0b15d1916497f3e68fc3fab98bec20be370cba'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'Prepárese para escuchar las historias de su vida en casi toda la clase, es pura vida el profe, califica lo justo, ayuda depende y se va guiando de una rúbrica que la da al principio del semestre muy puntual con todo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2025-11-12T00:00:00+00:00'::TIMESTAMPTZ, '8255daccd3798463a896bf24f82c6d67565cef528c3d1c5d2cccf0d4ee89b880'::TEXT, ARRAY[625]::BIGINT[]),
    (140::BIGINT, 'Es un buen profesor, sus clases son divertidas y las evaluaciones no son tan difíciles. Es muy amable y agradable.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2025-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'b86df4e48807c988d39a73f05df4cadeed64852a214672e20aff2f79604bb364'::TEXT, ARRAY[545]::BIGINT[]),
    (140::BIGINT, 'El profe es muy bueno, siempre da retroalimentación, y de verdad le interesa mucho que uno aprenda. Las evaluaciones están acorde a lo que se ve en el curso. Pd: hace mucho énfasis en la pronunciación.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2025-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'cc83ab90a306dcd9302c94f7056e1db18a7f0cc8c111945824fbb87ef50d9d14'::TEXT, ARRAY[625]::BIGINT[]),
    (140::BIGINT, 'Es buen profe y buena persona, incluso nos invito a un café frío a todo el grupo, solo que a veces si se distrae un poco contando historias a la hora de explicar. Pero en general buen profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'f899e66b64bcc088454280d1084d4511ea5c9fbc666af86876c3321df628094d'::TEXT, ARRAY[625]::BIGINT[]),
    (140::BIGINT, 'Como profesor es regular, pero como persona es un completo ASCO'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2024-11-08T00:00:00+00:00'::TIMESTAMPTZ, 'ab53337a3844950b2df1489125fcadda316dd7b61ef8d71581a32eaf0932a943'::TEXT, ARRAY[625, 545, 547, 541, 2525, 3263]::BIGINT[]),
    (140::BIGINT, 'Es un amor de profe, deja muchas presentaciones y quices, que en realidad le ayudan mucho a aprender, las clases son largas pero entretenidas, a veces suelta comentarios graciosos, el mejor profe de inglés que he tenido, el profe se preocupa por el aprendizaje del estudiante, 100% matricule con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Clases largas']::TEXT[], '2024-09-09T00:00:00+00:00'::TIMESTAMPTZ, '396ee7df1fb01ad4daf4b17df0b049e33714b27ae148500a233a20fb1962bf77'::TEXT, ARRAY[545]::BIGINT[]),
    (140::BIGINT, 'El curso es fácil, para nivel B1-B2 aprox. Explica muy bien, deja varios trabajos como presentaciones en clase, ayuda en todo lo que necesite. La clase es bastante larga, si no le hacen falta los créditos puede evitarla o guardarla.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, '9d76f80844ad87f429217327d80b14c1cae4edacab9e74be43c696958c6cd905'::TEXT, ARRAY[545]::BIGINT[]),
    (140::BIGINT, 'El profe es demasiado buena nota, en general siento que es una clase facil, solo que la asistencia es obligatoria, nunca llegó a gritar, solo que habla fuerte pero no de una forma irrespetuosa'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2024-04-05T00:00:00+00:00'::TIMESTAMPTZ, 'a5e0131d37f2474b8a8577a355555e081de127f81e8d9af4a84f8be314974749'::TEXT, ARRAY[545]::BIGINT[]),
    (140::BIGINT, 'LE ENCANTA GRITAR ! Evitenlo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-02-21T00:00:00+00:00'::TIMESTAMPTZ, 'cc77b50d82d68c0400d520a6796937c5a1fa5776812eb641dff57a817bcc95ca'::TEXT, ARRAY[625, 545, 547, 541, 2525, 3263]::BIGINT[]),
    (140::BIGINT, 'El profe es muy atento al estudiante, siempre ayuda y deja participar a todos, incentiva a que se hable inglés siempre para practicarlo, las clases son suaves y si hay errores en los exámenes el siempre los corrige, siempre contesta correos bastante rápido. Muy recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2024-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'a08e8927aff34349db564e8dafe23417c3db98bb25950313ebf4f92ed1f7237b'::TEXT, ARRAY[541]::BIGINT[]),
    (140::BIGINT, 'Si pueden hacer el diagnóstico y evitar el curso, es un ahorro de tiempo. No se puede faltar, el desde la primera clase dice que dos faltas y adiós. Es muy intenso, al final de semestre se puso de molesto e incluso llegó a gritar en varias ocasiones, quizá a veces sea bueno, pero es demasiado intens'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-01-17T00:00:00+00:00'::TIMESTAMPTZ, 'a5d74a6e7a8db4427b6dd245175227edf0c53f33a33ee4814feede02ad990618'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'El profe es muy organizado, es solo de prestar atención e ir con la materia al día para las evaluaciones. En todas las clases hay que hacer trabajos en clase con compañer@s aleatorios'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '8b82bc26771e075089c49a2d7cd4180c452f41b43d3c8b1b00137956ba707cf8'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'El profe es super pura vida, las clases las hace entretenidas, le gusta que participen, te ayuda mucho en la pronunciación y escritura, califica medio suave, si prestas atención y vas a consulta se te harán fáciles los quices y el examen.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '24863fcdf1e0ae6acf98c12373842450a5d4a3f52bbb6d433d6282ce32283293'::TEXT, ARRAY[625]::BIGINT[]),
    (140::BIGINT, 'Es muy organizado con la clase y los trabajos, si usted entrega lo que le pide y va a clases va a pasar sin problema, solo que cuidado con la asistencia, porque si queda a gente si falta más de 2 veces, o las que indique el programa del curso, es buena nota y vacilón.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '104c1925bffc7062c084a379d2a0e4aa725ade0440356069e04960eccd6fb290'::TEXT, ARRAY[2525]::BIGINT[]),
    (140::BIGINT, 'El 70% de la clase es en español. Facilísimo pasar incluso si no sabe inglés (exámenes y quizzes de marque con x) Eso sí, este banano casi me queda por ausencias (tuve que "enfermarme"), no es flexible en ese sentido'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '6dfd6617c2fbe484f642b10ac6146c2de5a34a7915590b60d9dbc6965e84bdeb'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'El profe es buena nota, las evaluaciones son en el GAAP al igual que las entregas; las clases no son pesadas y son bastante entretenidas, los trabajos en clase casi siempre se exponen en el aula. Es muy rígido con la asistencia so, no perdona ausencias injustificadas o tardías.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '89dbf111eafbeeb879d4858e9dfc212717ea2f4569f44ad2c850f4e388d55733'::TEXT, ARRAY[545]::BIGINT[]),
    (140::BIGINT, 'Excelente profe, se participa bastante en clase con actividades en pareja como grupal para luego exponer. Las evaluaciones son claras y califica suave. Le interesa que usted aprenda y da buena retroalimentación.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'ada30c3c8e087b097fec0f8523cd75d3fbf74f564a83d74bc296e5f52509133d'::TEXT, ARRAY[625]::BIGINT[]),
    (140::BIGINT, 'El profe es bastante bueno, si quiere mejorar su inglés matricule con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2023-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'e1c75b2607363371b8b682ee41190d625ae6763db9e02002c8ae1bdddc955ddc'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2023-05-20T00:00:00+00:00'::TIMESTAMPTZ, '29d79eb2318ea008eb4476684fbfa8bd9b2d9631b3addd702b7736e3425dff96'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'Es muy bueno explicando, se ve que realmente tiene vocación. Busca que se practique mucho en el ámbito conversacional y trata de que las clases sean dinámicas. En cualquier curso de inglés lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, '0b20b14babf5415a163b117cf1f65d9f4b110c8c798c696125e7dc91d04303a9'::TEXT, ARRAY[2379]::BIGINT[]),
    (140::BIGINT, 'Exelente profesor. Las clases son muy dinámicas y requieren de participación. El profe es muy divertido y la clase a pesar de ser larga se pasa rápido. Las tareas normalmente son forms, un poquillo largas pero fáciles, examenes solo 1 el cual también fue un forms. Hay exposiciones orales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'f36a40c5dbf8147b0ed8a08b9ef12a63da8b7391bcc3a0759ad7ac7fcfd9a94b'::TEXT, ARRAY[2379]::BIGINT[]),
    (140::BIGINT, 'Excelente profesor para cualquier curso de inglés, él se adapta al nivel que tienes y para él lo más importante es que usted practique el idioma'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2022-12-02T00:00:00+00:00'::TIMESTAMPTZ, '14a13b5d6cb283f8be5edd415fab1498d98e93943a4aec9bc005930230ec3596'::TEXT, ARRAY[625]::BIGINT[]),
    (140::BIGINT, 'Es de los mejores profes qué hay!!, explica muy bien y fomenta mucho el trabajo en equipo, las evaluaciones son un toque rudas si usted no sabe nada de inglés, si usted ya tiene un nivel intermedio el curso es un queque, lo recomiendo 100%'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2022-10-27T00:00:00+00:00'::TIMESTAMPTZ, '3f61d250d173fd2f2c307edbe9eabac6d315b564c185fc57905f7360a20433c8'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'Las clases son buenas y explica bien. SIEMPRE se trabaja en equipo y hay tareas todas las semanas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2022-10-07T00:00:00+00:00'::TIMESTAMPTZ, '59f1b13de1b9c212915dc3a0ddaaad69b330e426a7ec706e9bc1ad9239f1be54'::TEXT, ARRAY[625, 545, 547, 541, 2525, 3263]::BIGINT[]),
    (140::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-30T00:00:00+00:00'::TIMESTAMPTZ, '5941ef4c80d4627fb4dd3bbeb619f0370ba9e79444f2809520bbdd6de1d039a0'::TEXT, ARRAY[545]::BIGINT[]),
    (140::BIGINT, 'Excelente profesor, explica muy bien y siempre está dispuesto a ayudar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'La participación importa']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '61e7c3846ba94fe041b5c51a9a77a1a659cd9300a2217f6980a9e14b1e357052'::TEXT, ARRAY[625]::BIGINT[]),
    (140::BIGINT, 'Deja varios trabajos, pero lo explica antes y te da la semana para prepararte para ellos. Es muy amable y responde cualquier duda.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'cfce8c7f0b4f04c54de25b4a36527c22d7fece70637b6731265657983d48a6f0'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'No tengo quejas con este profe, se preocupa y entiende a los estudiantes. Le gusta hablar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, '7e9ea8b1aa54b457d1d2706398788ec9f666d95c37bf4019119e52136ee94a5f'::TEXT, ARRAY[625, 545, 547, 541, 2525, 3263]::BIGINT[]),
    (140::BIGINT, 'Es bastante bueno, le gusta ayudar mucho incluso puede ser un poco aburrido pero, en general enseña bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'f474f19c7d7e140c690ab7cd291de2e0b2d31240a250b6eb459c487ed9603693'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2022-05-24T00:00:00+00:00'::TIMESTAMPTZ, 'c58a0fa34a817992f0acf385e922e00baf1661cb04bc004d9eb138531ea1b9d2'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-03T00:00:00+00:00'::TIMESTAMPTZ, '7a28819900e1ce69ce2279b6ba328fb2c8a7d3507edf4a495417b031d4056128'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'No lo recomiendo para nada es muy complicado explica poco y no tiene ética para dar la clase.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-02-04T00:00:00+00:00'::TIMESTAMPTZ, '8bb2dfa0efd8c60d28b7cf643a9aee82f6116eece5d32363eb4338cf322e75a1'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'excelente profe, califica rudo, ayuda mucho, le gusta la participación en clase, deja asignaciones todas las clases que tienen que ver con el tema visto, una clase muy amena.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2022-02-01T00:00:00+00:00'::TIMESTAMPTZ, '347570bb4b1a4ea30514b1d02f463366d07570bfd6ff15db6dd8c720508dc32a'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'Muy amable, siempre nos dio la oportunidad de hablar con los demás compañeros en ingles y con el, siempre nos ayudo mucho y aclaro todas las dudas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'e1a1a7e2e07601b88a4a72339e1c70a5b87faab3e4ff7cf103f9373d30b87316'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'Las clases con el son entretenidas, pero hay que participar mucho, deja tareas todas las semanas, bastantes quiz, y mucho trabajo en equipo. Califica muy duro mas que todo en la pronunciacion, si decis una palabra un poco mal te baja puntos, y si haces pausas cortas tambien. TIENE MUY POCA PACIENCIA'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '0484b040858bf2977ee9438f846350477b5e9875e6b790b0e2f368918146ab1c'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'Si su pronunciacion no es perfecta y se quiere, NO MATRICULE CON EL'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'a54392aa0c367091fb0c6c9c7ae193920a387d2a5b2d38397c5109bb2b1ad143'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'Es difícil, le gusta la parte de comunicación oral. Exige mucho pero ayuda en las tareas. Curso virtual lo hace más llevadero'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-05T00:00:00+00:00'::TIMESTAMPTZ, '4f79d56b29d2929f06280bb05fa781838ed4202345092822f740bec0d715dff7'::TEXT, ARRAY[545]::BIGINT[]),
    (140::BIGINT, 'El profe no enseña lo básico , se manda a temas sin ver cosas básicas. Yo ya estoy en ingles 1 con Patricia, ella nos hizo una retroalimentación de este curso y estoy viendo todo lo que este profe no enseñó desde un principio. Si eres nuevo en el inglés, no matricules con él. Se enoja en clases'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-05T00:00:00+00:00'::TIMESTAMPTZ, '9ab8a866f343ec9572609b3f7e4cdce84c74f619a23f3aeadb7980b87dfb040a'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'El profesor no es malo, pero si te cuesta la pronunciación, aunque tengas un buen nivel de inglés, no te sorprendas si los Oral Quiz que hagas tengan calificaciones muy bajas, ya que califica muy duro eso, lo peor es que a muchas personas les cuesta la pronunciación y aun así, no ayuda en esa área.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Aspectos de calificación claros']::TEXT[], '2021-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'da4d4442842e06e11c119b7fb543a649b9e1181339ca1e91f57265d18b86d026'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'El mae como profe es muy bueno y en realidad es ciertamente fácil pasar con él en comparación con otros profes. Como persona no le gusta que lo corrijan, para él todo es una falta de respeto y se nota que brinda más apoyo a las mujeres. Si quiere pasar matricule con él.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'a35a16492e6601a81a1e254d991e351322ee6f0239261d50a39f476c518dd2e1'::TEXT, ARRAY[625]::BIGINT[]),
    (140::BIGINT, 'Bune profe, si no sabes inglés te va a costar porque evalúa ciertas cosas un poco estricto, pero no deja de ser bueno ya que trata a los estudiantes y a veces vacila. Recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-27T00:00:00+00:00'::TIMESTAMPTZ, '28bf4ead5a6eac27334a293891b36ff3f043a80ffc99ff80a38cdee1d3deee93'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'Si usted no es bueno en ingles ni se le ocurra matricular ingles basico con el, es ironico, pero califica demasiado duro cosas muy basicas porque espera que usted en los oral quiz tenga una pronunciacion igual o mejor que la de el.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2021-05-07T00:00:00+00:00'::TIMESTAMPTZ, '1c70d83a11cf3b10a6959ac6c7d55a3eded9b729961e4c63b3000d85ddbe6866'::TEXT, ARRAY[539]::BIGINT[]),
    (140::BIGINT, 'Un profesor que sabe muy bien y muy bueno! Se lo recomiendo bastante y se preocupa mucho por el estudiante! Lo llevé en virtual y es del TEC de San Carlos'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'La participación importa']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'd70ad4835424c5ede8938f272c7193b017bbc3706ed4ff89439ad09207378212'::TEXT, ARRAY[547]::BIGINT[]),
    (140::BIGINT, 'Buen profe, harto friki, que la fuerza lo acompañe siempre.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-15T00:00:00+00:00'::TIMESTAMPTZ, '8531e912678b73905147df524238bd4af7153dc040d2c922760804bb1c8e0100'::TEXT, ARRAY[545]::BIGINT[]),
    (140::BIGINT, 'De los mejores profesores que he tenido. Se preocupa por el aprendizaje del estudiante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2021-01-02T00:00:00+00:00'::TIMESTAMPTZ, 'fde36727b1f6c4c32bd829428697e2d23150a02d51a8910610b93b7fb3510ba3'::TEXT, ARRAY[545]::BIGINT[]),
    (140::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2020-12-14T00:00:00+00:00'::TIMESTAMPTZ, '9f4a5013ba210d4c9c49d0259b0b89eebb7b1bc9dd730aef9805d4e4fb21a951'::TEXT, ARRAY[547]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
